"""Observe one unchanged training trajectory after the scientific study has finished."""
import hashlib
import json
import sys
from pathlib import Path

import torch
from scripts.e2e import continual_learning_eval as study

root = Path(__file__).parent
original = json.loads((root / 'result.json').read_text())
failed = next(r for r in original['failed_arms'] if r['mode'] == 'bio_no_sleep')
seed = failed['seed']
config = study.ContinualEvalConfig()
probe, streams = study._inputs(config, seed)
model = None
names = {}
first = []
milestones = []
seen = set()
peak = {}
phase = None
step = 0
handles = []


def describe(tensor):
    a = tensor.detach()
    finite = torch.isfinite(a)
    return {'dtype': str(a.dtype), 'shape': list(a.shape), 'finite': int(finite.sum()), 'total': a.numel(),
            'nan': int(a.isnan().sum()), 'positive_inf': int(a.isposinf().sum()), 'negative_inf': int(a.isneginf().sum()),
            'finite_max_abs': float(a[finite].abs().max()) if finite.any() else None}


def observe(stage, name, value):
    if not isinstance(value, torch.Tensor) or not value.is_floating_point() or not value.numel():
        return
    key = stage + ':' + name
    v = value.detach()
    if torch.isfinite(v).all():
        maximum = float(v.abs().max())
        if maximum > peak.get(key, 0.0):
            peak[key] = maximum
        return
    if key in seen:
        return
    seen.add(key)
    event = {'phase': phase, 'step': step, 'site': stage, 'tensor': name, 'previous_observed_finite_max_abs': peak.get(key), **describe(v)}
    if len(first) < 16:
        first.append(event)
    category = stage.split('/')[0]
    if not any(r['category'] == category for r in milestones):
        milestones.append({'category': category, **event})


def profile(frame, event, arg):
    global model, names, phase, step
    path = frame.f_code.co_filename
    fn = frame.f_code.co_name
    if event == 'return' and fn == '_model' and path.endswith('/continual_learning_eval.py'):
        model = arg
        names = {id(m): n or 'model' for n, m in model.named_modules()}
        for name, p in model.named_parameters():
            if p.requires_grad:
                def inspect_gradient(grad, name=name):
                    observe('gradient/backward', name, grad)
                    return None
                handles.append(p.register_hook(inspect_gradient))
    if event == 'call' and fn == '_logits' and path.endswith('/continual_learning_eval.py'):
        caller = frame.f_back
        if 'phase' in caller.f_locals:
            phase = caller.f_locals['phase']
            step = caller.f_locals.get('step', 0)
    if model is None or event != 'return':
        return
    owner = frame.f_locals.get('self')
    if path.endswith('/synaptic.py') and fn in ('_apply_hebb_weight_writes', '_update_hebb_traces', 'hebb_fast', 'consolidate', 'update'):
        module_name = names.get(id(owner))
        if module_name is None:
            return
        for k, v in frame.f_locals.items():
            observe('plasticity/' + fn, module_name + '.' + k, v)
        for k, v in owner.named_buffers(recurse=False):
            observe('buffer/' + fn, module_name + '.' + k, v)
        for k, v in owner.named_parameters(recurse=False):
            observe('parameter/' + fn, module_name + '.' + k, v)
    if path.endswith('/adamw.py') and fn == 'step':
        for k, v in model.named_parameters():
            observe('optimizer/step', k, v)
    if path.endswith('/continual_learning_eval.py') and fn == '_logits':
        observe('prediction/logits', 'model.logits', arg)


def on_forward(module, _inputs, output):
    name = names.get(id(module))
    if name is None:
        return
    for index, value in enumerate(output if isinstance(output, tuple) else (output,)):
        observe('forward/' + type(module).__name__, name + f'.output[{index}]', value)


fh = torch.nn.modules.module.register_module_forward_hook(on_forward)
try:
    sys.setprofile(profile)
    with torch.random.fork_rng(devices=[]):
        result = study._run_arm(config, seed, 'bio_no_sleep', probe, streams)
finally:
    sys.setprofile(None)
    fh.remove()
    for handle in handles:
        handle.remove()
if not first or any(result[k] != failed[k] for k in ('phase', 'step_in_phase', 'reason', 'parameter_sha256_at_stop', 'last_finite_training_loss')):
    raise RuntimeError('instrumented trajectory did not reproduce the scientific failure')
report = {'seed': seed, 'mode': 'bio_no_sleep', 'unchanged_input_and_parameter_trajectory_at_failure': True,
          'failed_arm': {k: failed[k] for k in ('phase','step_in_phase','reason','last_finite_training_loss','wake_layer_writes_at_stop','parameter_sha256_at_stop')},
          'scope': 'First nonfinite observation among traced tensor outputs, registered parameter gradients, Hebbian function return locals, buffers/parameters after writes and optimizer steps. Finite maxima refer to earlier observations at the same site. Hooks return all training values unchanged.',
          'first_events': first, 'first_per_category': milestones, 'original_result_sha256': hashlib.sha256((root/'result.json').read_bytes()).hexdigest(),
          'evaluator_sha256': original['source_sha256'], 'diagnostic_source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
          'diagnostic_source': Path(__file__).read_text()}
(root / 'first_nonfinite.json').write_text(json.dumps(report, allow_nan=False, indent=2) + '\n')
